// generator/env-generator.js
// Auto-generates a .env file for the generated system
// based on what modules are installed and what envVars they declare.

const fs = require("fs-extra");
const path = require("path");
const crypto = require("crypto");

/**
 * Generates a random secret string (for JWT_SECRET, NEXTAUTH_SECRET, etc.)
 * @returns {string}
 */
function generateSecret() {
  return crypto.randomBytes(32).toString("hex");
}

/**
 * Returns a sensible placeholder or auto-generated value for an env var.
 * @param {string} varName
 * @param {string} systemName
 * @returns {string}
 */
function valueFor(varName, systemName) {
  const upper = varName.toUpperCase();

  if (upper.includes("SECRET") || upper.includes("KEY")) {
    return generateSecret();
  }
  if (upper === "DATABASE_URL") {
    return `postgresql://postgres:password@localhost:5432/${systemName}_db`;
  }
  if (upper.includes("URL") || upper.includes("URI")) {
    return `http://localhost:3000`;
  }

  return `your_${varName.toLowerCase()}_here`;
}

/**
 * Generates a .env file in the target system directory.
 *
 * @param {object[]} manifests - ordered module manifests
 * @param {string} targetDir - path to the generated system
 * @param {string} systemName - name of the system being generated
 */
async function generateEnvFile(manifests, targetDir, systemName) {
  const lines = [
    `# ============================================================`,
    `# Auto-generated by System Factory`,
    `# System: ${systemName}`,
    `# Generated: ${new Date().toISOString()}`,
    `# ============================================================`,
    ``,
    `# Database`,
    `DATABASE_URL="${valueFor("DATABASE_URL", systemName)}"`,
    ``,
  ];

  for (const manifest of manifests) {
    const vars = manifest.envVars || [];
    if (vars.length === 0) continue;

    lines.push(`# ${manifest.name} module`);
    for (const varName of vars) {
      lines.push(`${varName}="${valueFor(varName, systemName)}"`);
    }
    lines.push("");
  }

  const envPath = path.join(targetDir, ".env");
  await fs.writeFile(envPath, lines.join("\n"));

  // Also write a .env.example with placeholders (safe to commit)
  const exampleLines = lines.map((line) => {
    // Replace generated secrets with placeholder text in the example
    if (line.includes("=") && !line.startsWith("#")) {
      const [key] = line.split("=");
      const upper = key.toUpperCase();
      if (upper.includes("SECRET") || upper.includes("KEY")) {
        return `${key}="your_${key.toLowerCase()}_here"`;
      }
    }
    return line;
  });

  const examplePath = path.join(targetDir, ".env.example");
  await fs.writeFile(examplePath, exampleLines.join("\n"));

  console.log(`  ✅ .env generated (with auto-generated secrets)`);
  console.log(`  ✅ .env.example generated (safe to commit)`);
}

module.exports = { generateEnvFile };
